// Cheatsheet HTML — 8-part structure per Part 5.1, reusing the existing
// .cs-flow / .cs-node / .cs-table / .cs-bar / .cs-trap / .cs-tip classes.
export const FICO_CHEATSHEETS = {
  'fi-day-1': '<div class="cs-bar">Enterprise Structure Hierarchy</div><div class="cs-flow"><span class="cs-node">CLIENT</span><span class="cs-arrow">►</span><span class="cs-node">COMPANY CODE</span><span class="cs-arrow">►</span><span class="cs-node green">CONTROLLING AREA</span><span class="cs-arrow">►</span><span class="cs-node amber">SEGMENT</span></div><div class="cs-section"><p><b>Company</b> = consolidation entity, can span several Company Codes. <b>Company Code</b> = independent legal entity, own statutory balance sheet + P&amp;L. <b>Business Area</b> = legacy cross-CC reporting, phased out. <b>Segment</b> = the S/4 answer, derived from Profit Center.</p></div><table class="cs-table"><tr><th>Org Unit</th><th>Assigned To</th><th>Cardinality</th></tr><tr><td>Company Code → Controlling Area</td><td>One Controlling Area per CC</td><td>N:1</td></tr><tr><td>Controlling Area → Company Codes</td><td>Many CCs per Controlling Area</td><td>1:N</td></tr><tr><td>Credit Control Area → Company Codes</td><td>Group-level credit risk</td><td>1:N</td></tr><tr><td>Segment</td><td>Derived from Profit Center</td><td>Auto</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>ACDOCA</b> carries parallel currencies natively on every line — no separate currency conversion tables to reconcile. <b>Segment replaces Business Area</b> as the primary cross-entity reporting dimension. <b>Fiori Spaces/Pages/Business Roles</b> replace static T-code menu authorization.</p></div><div class="cs-section"><p><b>Currency Types:</b> Company Code currency + Group currency (fixed) + up to 8 freely definable types — all on the same ACDOCA line. <b>Fiscal Year Variant</b> drives posting period determination → close timing → depreciation → CO period locks.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Cross-CC Controlling requires identical operating chart of accounts AND fiscal year variant</b> — missing either breaks real-time FI-CO integration.</p><p>• <b>Business Area ≠ Segment.</b> Segment is derived from Profit Center; Business Area is legacy and not the S/4 path.</p><p>• <b>Credit Control Area ≠ Credit Segment (FSCM).</b> A mapping between the two must exist for FSCM checks.</p><p>• <b>Fiori "no tiles visible" is almost always a Business Role/catalog mapping gap</b>, not a missing authorization object.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Company Code = legal entity. Controlling Area = 1:N over Company Codes.</p><p>• Segment (not Business Area) = S/4 cross-entity reporting, derived from Profit Center.</p><p>• Up to 10 currency types, all native on ACDOCA.</p><p>• Enterprise Structure is locked first — every later FI/CO tab assumes it.</p></div>',

  'fi-day-2': '<div class="cs-bar">Posting Period Control</div><div class="cs-flow"><span class="cs-node">FISCAL YEAR VARIANT</span><span class="cs-arrow">►</span><span class="cs-node">POSTING PERIOD VARIANT (OB52)</span><span class="cs-arrow">►</span><span class="cs-node green">PERIOD AUTH GROUP</span></div><div class="cs-section"><p><b>OB52</b> sets permitted posting periods per account type (A/D/K/S/M) at the posting period variant level. <b>Period Authorization Group</b> layers on top to restrict an open period to specific users only — the close-team-only window.</p></div><table class="cs-table"><tr><th>Posting Key Pair</th><th>Use</th></tr><tr><td>40 / 50</td><td>G/L debit / credit</td></tr><tr><td>01 / 11</td><td>Customer invoice / credit</td></tr><tr><td>21 / 31</td><td>Vendor invoice / credit</td></tr><tr><td>25 / 35</td><td>Vendor debit / credit clearing</td></tr></table><div class="cs-bar green">Field Status — The Three-Way Conflict</div><div class="cs-flow"><span class="cs-node red">SUPPRESS</span><span class="cs-arrow">►</span><span class="cs-node">DISPLAY</span><span class="cs-arrow">►</span><span class="cs-node">REQUIRED</span><span class="cs-arrow">►</span><span class="cs-node amber">OPTIONAL</span></div><div class="cs-section"><p>Posting key, Field Status Group (on the G/L account), and Account Group (on vendor/customer master) can each mark a field differently. <b>Suppress always wins</b>, regardless of what the others say.</p></div><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p>Posting keys still exist in the underlying data model, but <b>Fiori apps abstract them</b> behind a simple debit/credit field — teach both the config object and the app behavior. Document types can be assigned to specific <b>ledger groups</b> for ledger-specific postings.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Special periods 13-16 have no calendar days</b> — year-end adjustments only.</p><p>• <b>Suppress beats Required</b> — a "required" field can still disappear entirely.</p><p>• <b>Missing document type-to-ledger assignment</b> silently excludes a non-leading ledger.</p><p>• <b>Tolerance groups split by seniority</b> — junior vs senior clerk payment write-off limits.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• OB52 = period open/close by account type. Period Auth Group = who, on top of that.</p><p>• 40/50, 01/11, 21/31, 25/35 — memorize the posting key set.</p><p>• Field status priority: Suppress &gt; Display &gt; Required &gt; Optional.</p><p>• Tolerance groups: G/L level + per-employee level.</p></div>',

  'fi-day-3': '<div class="cs-bar">Chart of Accounts Hierarchy</div><div class="cs-flow"><span class="cs-node">OPERATING COA</span><span class="cs-arrow">►</span><span class="cs-node green">GROUP COA</span><span class="cs-arrow">►</span><span class="cs-node amber">COUNTRY COA</span></div><div class="cs-section"><p><b>Operating</b> = daily postings, assigned to Company Code. <b>Group</b> = consolidation across Company Codes with different operating charts. <b>Country</b> = local statutory account layout, alongside the operating COA.</p></div><table class="cs-table"><tr><th>G/L Account Type</th><th>Purpose</th></tr><tr><td>Balance Sheet</td><td>Asset / liability / equity accounts</td></tr><tr><td>Non-Op. Expense/Income</td><td>P&amp;L, non-operating</td></tr><tr><td>Primary Costs/Revenue</td><td>P&amp;L, CO-relevant (replaces ECC cost element)</td></tr><tr><td>Secondary Costs</td><td>CO-only allocations, no external revenue/expense</td></tr><tr><td>Cash Account</td><td>Integrates with Bank Account Management</td></tr></table><div class="cs-bar green">G/L Master — 3 Segments</div><div class="cs-section"><p><b>Chart of Accounts segment:</b> description, account type — shared across all CCs on that COA. <b>Company Code segment:</b> currency, tax category, reconciliation link. <b>Controlling relevance:</b> cost/revenue elements are CO-relevant automatically via account type.</p></div><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>G/L Account Type merges FI and CO master data</b> — a secondary cost element is just a G/L account, not a separate KA06 transaction. Maintained via the <b>"Manage G/L Account Master Data"</b> Fiori app.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Where do you create a secondary cost element in S/4?"</b> → G/L master, account type Secondary Costs. #1 trap question.</p><p>• <b>Reconciliation accounts cannot be posted to directly</b> — must go through AP/AR sub-ledger.</p><p>• <b>Changing account type after postings exist is high-risk</b> — historical CO logic assumes type consistency.</p><p>• <b>Open Item Management cannot be toggled on an account with existing balances</b> without a clean-up/migration.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Operating COA = daily use. Group COA = consolidation. Country COA = local statutory.</p><p>• 5 account types: Balance Sheet, Non-Op Exp/Inc, Primary Costs/Revenue, Secondary Costs, Cash.</p><p>• P&amp;L Statement Account Type → exactly one Retained Earnings Account.</p><p>• Reconciliation accounts: sub-ledger posts, GL never posts directly.</p></div>',

  'fi-day-4': '<div class="cs-bar">Document Structure</div><div class="cs-flow"><span class="cs-node">BKPF (Header)</span><span class="cs-arrow">►</span><span class="cs-node green">ACDOCA (Line Items)</span><span class="cs-arrow">►</span><span class="cs-node amber">BSEG (Compatibility View)</span></div><div class="cs-section"><p><b>Park:</b> complete document, later-postable, visible in approval queues. <b>Hold:</b> incomplete private draft, only the entering user sees it, never posts.</p></div><table class="cs-table"><tr><th>Clearing Type</th><th>Effect</th></tr><tr><td>Partial</td><td>Original item stays open, original baseline date preserved</td></tr><tr><td>Residual</td><td>Original item closes, new item created with NEW baseline date</td></tr></table><div class="cs-bar green">Reversal &amp; Accruals</div><div class="cs-section"><p><b>Reset &amp; Reverse:</b> undoes clearing first, then reverses. <b>Accrual Engine:</b> automates recurring accrual/deferral postings and their scheduled reversal.</p></div><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>ACDOCA is the single line-item table</b> — no index/totals reconciliation like BSEG/BSIS/BSAS. <b>Ledger group posting</b> restricts an entry to specific accounting-principle ledgers.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Park vs Hold</b> — Park is workflow-visible/postable, Hold is private/incomplete.</p><p>• <b>Residual clearing resets the baseline date</b> — affects dunning and payment terms.</p><p>• <b>"Why can\'t I reverse?"</b> chain: cleared, period closed, cross-company, wrong reason code.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• BKPF = header, ACDOCA = line items, BSEG = compatibility only.</p><p>• Partial preserves baseline date; residual resets it.</p><p>• Post General Journal Entries, Manage Journal Entries, Verify Journal Entries = the 3 core apps.</p></div>',

  'fi-day-5': '<div class="cs-bar">ACDOCA — What It Absorbed</div><div class="cs-flow"><span class="cs-node">BSEG</span><span class="cs-node">COEP</span><span class="cs-node green">FAGLFLEXA</span><span class="cs-node">ANEP</span><span class="cs-node amber">MLIT</span></div><div class="cs-section"><p>All merged into <b>one Universal Journal line-item table</b>. <b>Leading Ledger (0L):</b> primary accounting principle, always active. <b>Non-leading ledgers:</b> alternative principles, grouped via Ledger Groups.</p></div><table class="cs-table"><tr><th>Splitting Type</th><th>Logic</th></tr><tr><td>Passive</td><td>Inherits split from referenced document (e.g. payment follows invoice)</td></tr><tr><td>Active</td><td>Derives its own split via splitting rules</td></tr></table><div class="cs-bar green">Zero-Balance Flag</div><div class="cs-section"><p>Forces a splitting characteristic (Segment, Profit Center) to balance to zero <b>within each document</b>. Without it, segment-level "balance sheets" won\'t actually balance even though the Company Code total is fine.</p></div><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>Extension ledgers</b> (standard/simulation/prediction) have no ECC equivalent. <b>Predictive accounting</b> posts commitments/statistical data to a prediction ledger without touching actuals.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Passive vs active splitting</b> — the single most-asked splitting question.</p><p>• <b>Missing zero-balance flag</b> = segment-level reports don\'t balance.</p><p>• <b>Splitting can activate post go-live</b> — but it\'s a project, historical data doesn\'t retroactively split.</p><p>• <b>Extension ledger data doesn\'t exist in the underlying standard ledger.</b></p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• ACDOCA = BSEG+COEP+FAGLFLEXA+ANEP+MLIT, one table.</p><p>• Passive = inherits split. Active = derives its own.</p><p>• Zero-balance flag = the balancing mechanism, not derivation alone.</p></div>',

  'fi-day-6': '<div class="cs-bar">Business Partner — Mandatory in S/4</div><div class="cs-flow"><span class="cs-node">BUSINESS PARTNER</span><span class="cs-arrow">►</span><span class="cs-node green">FLVN00 (General)</span><span class="cs-node amber">FLVN01 (Company Code)</span></div><div class="cs-section"><p><b>CVI</b> syncs BP and vendor sub-object numbers automatically. <b>Vendor Account Group</b> controls number range + field status — mirrors the G/L Account Group concept (FI Day 3).</p></div><table class="cs-table"><tr><th>Concept</th><th>Detail</th></tr><tr><td>Down Payment</td><td>Special G/L indicator A, alternative reconciliation account</td></tr><tr><td>Baseline Date</td><td>Drives F110 selection AND dunning eligibility</td></tr><tr><td>Partial vs Residual</td><td>Same logic as FI Day 4, applied to vendor payments</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>XK01/FK01 obsolete</b> — BP is the only path (classic "have you touched S/4?" filter). <b>Extended Withholding Tax mandatory</b> — classic WHT not supported.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Missing BP role → cannot post.</b> Most common unexplained AP posting failure.</p><p>• <b>Down payment uses special GL indicator A</b> + a different reconciliation account.</p><p>• <b>Baseline date drives both APP selection and dunning</b> — one field, two downstream effects.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• BP only, no FK01/XK01. CVI keeps numbers in sync.</p><p>• Down payment ≠ regular invoice — separate special GL + recon account.</p><p>• Partial preserves baseline date, residual resets it (same as FI Day 4).</p></div>',

  'fi-day-7': '<div class="cs-bar">F110 — The Payment Run</div><div class="cs-flow"><span class="cs-node">PARAMETERS</span><span class="cs-arrow">►</span><span class="cs-node">PROPOSAL</span><span class="cs-arrow">►</span><span class="cs-node green">PAYMENT RUN</span><span class="cs-arrow">►</span><span class="cs-node amber">PAYMENT MEDIUM</span></div><div class="cs-section"><p><b>FBZP — 5 blocks:</b> all company codes, paying company code, payment methods per country, payment methods per company code, bank determination (ranking, accounts, amounts, value date, charges).</p></div><table class="cs-table"><tr><th>Tool</th><th>Role</th></tr><tr><td>Bank Account Management (BAM)</td><td>House banks, account IDs — replaces FI12</td></tr><tr><td>Payment Medium Workbench (PMW)</td><td>File/format generation — replaces RFFO*</td></tr><tr><td>Electronic Bank Statement (EBS)</td><td>Import, interpret, match, post bank transactions</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p>Bank master data lives in <b>BAM, not FI12</b>. Classic RFFO print programs replaced by <b>PMW</b>.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Proposal picked nothing" chain:</b> payment method (BP vs doc), payment block, bank determination amounts, house bank, due date, minimum amount.</p><p>• <b>EBS unmatched items → clearing account</b>, not a failed import.</p><p>• <b>Value date ≠ posting date ≠ document date.</b> Three distinct dates.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• F110: Parameters → Proposal → Run → Medium.</p><p>• 5 FBZP blocks — memorize for the "why did nothing get selected" question.</p><p>• BAM = bank master. PMW = file format. EBS = statement automation.</p></div>',

  'fi-day-8': '<div class="cs-bar">Customer as Business Partner</div><div class="cs-flow"><span class="cs-node">BUSINESS PARTNER</span><span class="cs-arrow">►</span><span class="cs-node green">FLCU00 (General)</span><span class="cs-node amber">FLCU01 (Company Code)</span></div><div class="cs-section"><p>Mirrors FI Day 6\'s vendor pattern. <b>Dunning Area:</b> different dunning rules per business unit within one Company Code. <b>Dunning run</b> respects grace days, minimum amounts, and item/account-level blocks.</p></div><table class="cs-table"><tr><th>FSCM Concept</th><th>Detail</th></tr><tr><td>Credit Segment</td><td>What FSCM actually scores/limits against (not Credit Control Area directly)</td></tr><tr><td>Static Check</td><td>Point-in-time exposure vs limit</td></tr><tr><td>Dynamic Check</td><td>Adds a forward-looking horizon window</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>FSCM Credit Management mandatory</b> — classic FD32 logic out of scope. <b>Credit Segment ↔ Credit Control Area mapping</b> must exist for checks to resolve.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Customer wasn\'t dunned"</b> — check grace days, min amount, dunning block, payment block, last-dunned date.</p><p>• <b>Passes at order, blocks at delivery</b> — other orders consumed exposure between the two SD trigger points.</p><p>• <b>Credit Segment ≠ Credit Control Area</b> naming — common trap.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• FLCU00/01 mirrors FLVN00/01. Same BP pattern both sides.</p><p>• FSCM scores Credit Segment, not Credit Control Area directly.</p><p>• Item interest vs balance interest — different calculation bases.</p></div>',

  'fi-day-9': '<div class="cs-bar">Chart of Depreciation → Depreciation Areas</div><div class="cs-flow"><span class="cs-node">CHART OF DEPRECIATION</span><span class="cs-arrow">►</span><span class="cs-node green">DEPRECIATION AREAS</span><span class="cs-arrow">►</span><span class="cs-node amber">LEDGER / ACCOUNTING PRINCIPLE</span></div><div class="cs-section"><p><b>New AA is mandatory:</b> every depreciation area posts in real time — no privileged "area 01," no ASKB reconciliation, no delta areas. Asset line items live in <b>ACDOCA</b>.</p></div><table class="cs-table"><tr><th>Concept</th><th>Detail</th></tr><tr><td>Technical Clearing Account</td><td>Splits acquisition into operational + valuating parts (mandatory, integrated acquisitions)</td></tr><tr><td>AuC</td><td>Assets under Construction — normally no depreciation, exceptions exist</td></tr><tr><td>Depreciation Key</td><td>Base method + declining balance + multilevel + period control</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>Real-time posting to all areas</b> — ASKB gone. <b>Delta depreciation areas eliminated.</b> <b>Technical clearing account mandatory</b> for integrated acquisitions.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Technical clearing account</b> — the single best S/4 AA differentiator question.</p><p>• <b>"Depreciation run failed"</b> chain: closed period, incomplete asset, blocked asset, ledger mismatch.</p><p>• <b>AuC normally no depreciation</b> — know the exceptions.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Every depreciation area posts real-time. No privileged area 01.</p><p>• Technical clearing account = operational vs valuating split.</p><p>• Asset postings now live in ACDOCA, not ANEP/ANLP.</p></div>',

  'fi-day-10': '<div class="cs-bar">FI Month-End Close Sequence</div><div class="cs-flow"><span class="cs-node">SUB-LEDGER CLOSE</span><span class="cs-arrow">►</span><span class="cs-node">GR/IR REGROUPING</span><span class="cs-arrow">►</span><span class="cs-node green">FX VALUATION</span><span class="cs-arrow">►</span><span class="cs-node amber">CARRYFORWARD</span></div><div class="cs-section"><p>Order matters — running steps out of sequence produces numbers that don\'t reflect the true period-end position. <b>Realized FX</b> = actual settlement. <b>Unrealized FX</b> = period-end estimate, typically reverses next period.</p></div><table class="cs-table"><tr><th>Term</th><th>Meaning</th></tr><tr><td>Conversion</td><td>At transaction/posting time</td></tr><tr><td>Valuation</td><td>Revalues open balances at period-end</td></tr><tr><td>Translation</td><td>Group/consolidation reporting across functional currencies</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>Embedded Analytics</b> (CDS views, Fiori apps) reports live off ACDOCA — no ETL. <b>Advanced Financial Closing / Financial Closing Cockpit</b> governs the checklist itself as an auditable workflow.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Account missing from balance sheet"</b> → unassigned Financial Statement Version node.</p><p>• <b>Unrealized FX should reverse next period</b> — check if the reversal run was actually executed.</p><p>• <b>Balance carryforward can be rerun</b> after post-close corrections.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Close order is a dependency chain, not an arbitrary checklist.</p><p>• Conversion (transaction time) vs Valuation (period-end) vs Translation (consolidation).</p><p>• P&amp;L flows to Retained Earnings via the FI Day 3 mapping.</p></div>',

  'co-day-1': '<div class="cs-bar">Controlling Area — The CO Foundation</div><div class="cs-flow"><span class="cs-node">COMPANY CODE</span><span class="cs-arrow">►</span><span class="cs-node green">CONTROLLING AREA (1:N)</span><span class="cs-arrow">►</span><span class="cs-node amber">CO COMPONENT MAP</span></div><div class="cs-section"><p>Cross-CC Controlling requires <b>same operating chart of accounts + same fiscal year variant</b> across every assigned CC. <b>Version 0</b> is the mandatory official plan baseline.</p></div><table class="cs-table"><tr><th>Currency</th><th>Represents</th></tr><tr><td>Controlling Area</td><td>The Controlling Area\'s own currency</td></tr><tr><td>Object</td><td>Cost center/order\'s own currency</td></tr><tr><td>Transaction</td><td>Currency of the original document</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>No reconciliation ledger</b> — FI and CO share the same Universal Journal document, so there is nothing to reconcile between them.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Only one TRUE CO object per line item</b> — everything else is statistical.</p><p>• <b>Why Version 0 is special</b> — the mandatory official baseline for standard reporting.</p><p>• <b>Mismatched fiscal year variants across CCs in one Controlling Area</b> break cross-CC CO reporting.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• CC : Controlling Area = N:1. Controlling Area : CC = 1:N.</p><p>• Same operating COA + same fiscal year variant = hard prerequisite.</p><p>• No reconciliation ledger — structural, not procedural, FI-CO sync.</p></div>',

  'co-day-2': '<div class="cs-bar">Cost Elements Are G/L Accounts</div><div class="cs-flow"><span class="cs-node">G/L ACCOUNT</span><span class="cs-arrow">►</span><span class="cs-node green">ACCOUNT TYPE: PRIMARY/SECONDARY COSTS</span><span class="cs-arrow">►</span><span class="cs-node amber">COST ELEMENT</span></div><div class="cs-section"><p><b>OKB9:</b> default account assignment — which cost object receives a posting with no manually entered cost object. <b>Full derivation:</b> document entry → OKB9 → substitution → cost element default.</p></div><table class="cs-table"><tr><th>Category</th><th>Meaning</th></tr><tr><td>1 / 11</td><td>Primary cost / Revenue</td></tr><tr><td>41</td><td>Overhead</td></tr><tr><td>42</td><td>Assessment (secondary) — keeps pool-level, hides original element</td></tr><tr><td>43</td><td>Internal activity allocation (secondary) — activity-level consumption</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>KA01/KA02/KA06 gone</b> — cost elements maintained entirely via the G/L account master. One master data object, one authorization concept.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Category 42 vs 43</b> — the single most-asked CO comparison.</p><p>• <b>Derivation sequence</b> as a troubleshooting scenario when OKB9 "doesn\'t fire."</p><p>• <b>Revenue elements can post to cost centers statistically</b> — not an error.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Cost element = G/L account with the right account type. No separate master.</p><p>• 42 = assessment, hides detail. 43 = activity allocation, activity-based.</p><p>• OKB9 is the default; substitution can override it.</p></div>',

  'co-day-3': '<div class="cs-bar">Standard Hierarchy — Mandatory, One Per Controlling Area</div><div class="cs-flow"><span class="cs-node">STANDARD HIERARCHY</span><span class="cs-arrow">►</span><span class="cs-node green">COST CENTER GROUPS</span><span class="cs-arrow">►</span><span class="cs-node amber">COST CENTER MASTER</span></div><div class="cs-section"><p>Cost center master carries category, hierarchy area, Profit Center (always <b>statistical</b> here), lock indicators, validity.</p></div><table class="cs-table"><tr><th>Reposting Type</th><th>Requires Original Document?</th></tr><tr><td>Reposting Line Items</td><td>Yes</td></tr><tr><td>Reposting Costs</td><td>No — new independent entry</td></tr></table><div class="cs-bar green">Fiori Apps</div><div class="cs-section"><p><b>Manage Cost Centers</b> (master data) and <b>Cost Centers – Plan/Actual</b> (variance reporting) — the daily-use apps for this tab.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Reposting Line Items needs the original document reference</b>, Reposting Costs does not.</p><p>• <b>Lock indicators</b> block specific transaction types, not the whole cost center.</p><p>• <b>Profit Center on a cost center is always statistical.</b></p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• One mandatory Standard Hierarchy per Controlling Area.</p><p>• Groups = flexible reporting layer, not a hierarchy replacement.</p><p>• True cost stays on the cost center; Profit Center gets the statistical copy.</p></div>',

  'co-day-4': '<div class="cs-bar">Distribution vs Assessment — The #1 CO Comparison</div><div class="cs-flow"><span class="cs-node">DISTRIBUTION</span><span class="cs-arrow">►</span><span class="cs-node green">KEEPS PRIMARY COST ELEMENT</span></div><div class="cs-flow"><span class="cs-node amber">ASSESSMENT</span><span class="cs-arrow">►</span><span class="cs-node red">SECONDARY COST ELEMENT (CAT. 42)</span></div><div class="cs-section"><p><b>Activity Types</b> always link to cost element category 43. <b>SKF:</b> Fixed (snapshot) vs Total (accumulated) — common tracing factors for allocation cycles.</p></div><table class="cs-table"><tr><th>Tool</th><th>Scope</th></tr><tr><td>Classic KSV5/KSU5</td><td>Still runs, but superseded</td></tr><tr><td>Universal Allocation</td><td>Fiori-managed, on ACDOCA — cost centers, profit centers, margin analysis</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>Universal Allocation is the strategic direction</b> — teach both classic and Universal, name Universal as current.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Distribution keeps primary cost element; Assessment uses secondary (42).</b> Memorize precisely.</p><p>• <b>Iterative processing</b> resolves cyclic sender/receiver relationships.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Distribution = transparent (primary). Assessment = consolidated (secondary, cat. 42).</p><p>• Activity Types ↔ category 43, always.</p><p>• Universal Allocation = the forward path, runs on ACDOCA.</p></div>',

  'co-day-5': '<div class="cs-bar">Internal Order Lifecycle</div><div class="cs-flow"><span class="cs-node">REL</span><span class="cs-arrow">►</span><span class="cs-node green">PLANNING &amp; BUDGET</span><span class="cs-arrow">►</span><span class="cs-node amber">SETTLEMENT</span></div><div class="cs-section"><p><b>Real vs Statistical:</b> only real orders can be settled. <b>Budget Profile Activation Types (1/2/3)</b> control warning vs hard-block behavior at tolerance limits.</p></div><table class="cs-table"><tr><th>Settlement Object</th><th>Purpose</th></tr><tr><td>Allocation Structure</td><td>Which cost elements settle, to which settlement cost elements</td></tr><tr><td>Settlement Profile</td><td>Valid receivers + settlement type (full/periodic)</td></tr><tr><td>Settlement Rule</td><td>The specific receiver split for this order</td></tr></table><div class="cs-bar amber">Investment Orders</div><div class="cs-section"><p><b>Investment Order → AuC → Fixed Asset</b> — same lifecycle as FI Day 9, from the CO/order side.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Statistical orders cannot be settled.</b></p><p>• <b>Allocation Structure vs Settlement Profile vs Source Structure</b> — three distinct objects, don\'t conflate.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Real orders settle; statistical orders don\'t.</p><p>• Budget Profile Activation Type = warning vs block severity.</p><p>• Investment order → AuC → Fixed Asset mirrors FI Day 9.</p></div>',

  'co-day-6': '<div class="cs-bar">Profit Center — A Field, Not a Ledger</div><div class="cs-flow"><span class="cs-node">ACDOCA LINE ITEM</span><span class="cs-arrow">►</span><span class="cs-node green">PROFIT CENTER FIELD</span><span class="cs-arrow">►</span><span class="cs-node amber">SEGMENT (DERIVED)</span></div><div class="cs-section"><p><b>Dummy Profit Center</b> = a derivation gap to investigate, not a permanent home. <b>Assignment Monitor</b> finds objects missing a profit center.</p></div><table class="cs-table"><tr><th>Concept</th><th>Role</th></tr><tr><td>Profit Center</td><td>Master data, own hierarchy + derivation</td></tr><tr><td>Segment</td><td>Typically derived FROM Profit Center</td></tr><tr><td>Business Area</td><td>Legacy — the concept Segment replaces</td></tr></table><div class="cs-bar amber">S/4 What Changed vs ECC</div><div class="cs-section"><p><b>GLPCA/GLPCT gone</b> — profit center reporting reads directly from ACDOCA.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Profit Center vs Segment vs Business Area</b> — three related, frequently confused concepts.</p><p>• <b>Profit-center balance sheets need document splitting</b>, not just derivation.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• PCA is a field on ACDOCA, not a separate ledger.</p><p>• Dummy profit center = fix the derivation gap, don\'t just clear it.</p><p>• Segment usually derives from Profit Center.</p></div>',

  'co-day-7': '<div class="cs-bar">Standard Cost Estimate — Create → Mark → Release</div><div class="cs-flow"><span class="cs-node">CREATE</span><span class="cs-arrow">►</span><span class="cs-node green">MARK (future price)</span><span class="cs-arrow">►</span><span class="cs-node amber">RELEASE (current price + revalues stock)</span></div><div class="cs-section"><p><b>Costing Variant</b> ties together Costing Type, Valuation Variant, Date Control, Quantity Structure Control, Transfer Control — the full "recipe."</p></div><table class="cs-table"><tr><th>Price Control</th><th>Behavior</th></tr><tr><td>S (Standard)</td><td>Fixed value, variance captured separately — recommended for actual costing</td></tr><tr><td>V (Moving Average)</td><td>Continuously updates with each transaction</td></tr></table><div class="cs-bar amber">Prerequisites</div><div class="cs-section"><p>BOM, Work Center, Routing, Activity Types must exist first — Product Cost Planning is fundamentally dependent on clean PP master data.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Mark vs Release</b> — Mark writes the future price, Release makes it standard and revalues stock.</p><p>• <b>"Cost estimate errored"</b> chain: missing BOM/routing, no component price, lot size, material status, date control.</p><p>• <b>Standard price (S) required for actual costing</b> scenarios (Material Ledger, CO-10).</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Create ≠ Mark ≠ Release — three distinct system impacts.</p><p>• S/4 recommends Price Control S with Material Ledger actual costing.</p><p>• Multi-level rollup is only as good as its weakest component estimate.</p></div>',

  'co-day-8': '<div class="cs-bar">Order Status Drives WIP vs Variance</div><div class="cs-flow"><span class="cs-node">REL (open)</span><span class="cs-arrow">►</span><span class="cs-node green">WIP CALCULATION</span></div><div class="cs-flow"><span class="cs-node amber">DLV / TECO</span><span class="cs-arrow">►</span><span class="cs-node red">VARIANCE CALCULATION (not WIP)</span></div><div class="cs-section"><p><b>WIP at Actual</b> (by period) vs <b>WIP at Target</b> (by order) — choose based on period-based or order-based reporting needs.</p></div><table class="cs-table"><tr><th>Variance Category</th><th>Signals</th></tr><tr><td>Input price / quantity</td><td>Purchasing or usage deviation</td></tr><tr><td>Scrap</td><td>Material loss during production</td></tr><tr><td>Remaining</td><td>Catch-all — large values suggest other categories are under-configured</td></tr></table><div class="cs-bar amber">S/4 Awareness</div><div class="cs-section"><p><b>Event-based production cost posting</b> enables real-time WIP/variance in some scenarios — same concepts, different timing. Settlement documents live in ACDOCA.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>DLV/TECO orders calculate variance, not WIP.</b> The single most-tested trap in this tab.</p><p>• <b>WIP by period vs by order</b> — match to the reporting scenario.</p><p>• <b>Target Cost Versions 0/1/2</b> represent different cost baselines.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Status is the gate: REL → WIP, DLV/TECO → variance.</p><p>• Make-to-order typically settles to Margin Analysis, not material.</p><p>• Large "remaining" variance = investigate other categories\' configuration.</p></div>',

  'fi-11': '<div class="cs-bar">Tax Procedure — Condition-Based</div><div class="cs-flow"><span class="cs-node">TAX CODE</span><span class="cs-arrow">►</span><span class="cs-node green">CONDITION TYPE</span><span class="cs-arrow">►</span><span class="cs-node amber">TAX ACCOUNT DETERMINATION</span></div><div class="cs-section"><p>Condition-based procedures (e.g. TAXINN) reuse the same condition technique as SD pricing. <b>Non-deductible tax</b> adds to material/expense cost. <b>Deferred tax</b> reports only once the deferral event (e.g. payment) occurs.</p></div><table class="cs-table"><tr><th>Concept</th><th>Detail</th></tr><tr><td>Tax Jurisdiction Code</td><td>State/county/city layering (US-style)</td></tr><tr><td>Plants Abroad</td><td>VAT registration from a plant, no separate legal entity</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Non-deductible ≠ ignored</b> — it becomes part of cost, not a recoverable tax account.</p><p>• <b>Deferred tax needs a transfer posting</b> when the trigger event occurs.</p><p>• <b>India GST specifics live in INT-6</b>, not here.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Condition-based tax = SD-style condition technique, reused.</p><p>• Plants Abroad ≠ new legal entity — it\'s a VAT reporting obligation only.</p></div>',

  'fi-12': '<div class="cs-bar">Special G/L Indicator Types</div><div class="cs-flow"><span class="cs-node">FREE OFFSETTING</span><span class="cs-node green">STATISTICAL</span><span class="cs-node amber">NOTED ITEM</span></div><div class="cs-section"><p><b>Statistical:</b> informational only (guarantees, deposits). <b>Noted Item:</b> memo posting, no G/L impact until conversion. <b>Cross-Company postings</b> create linked documents across Company Codes via a shared cross-company document number.</p></div><table class="cs-table"><tr><th>Tool</th><th>Function</th></tr><tr><td>Substitution (GGB1)</td><td>Auto-derives/replaces field values</td></tr><tr><td>Validation (GGB0)</td><td>Checks and blocks postings against rules</td></tr><tr><td>BRF+</td><td>Modern rule engine, supplements/replaces classic substitution</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Standard clearing can\'t clear across Company Codes</b> — needs a dedicated cross-company clearing transaction.</p><p>• <b>Substitution changes data; Validation only blocks.</b> Don\'t conflate the two.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Statistical = informational. Noted Item = memo until converted.</p><p>• Cross-company postings = separate documents, one shared reference number.</p></div>',

  'co-9': '<div class="cs-bar">Account-Based Margin Analysis — The S/4 Default</div><div class="cs-flow"><span class="cs-node">G/L ACCOUNTS</span><span class="cs-arrow">►</span><span class="cs-node green">REPLACE VALUE FIELDS</span><span class="cs-arrow">►</span><span class="cs-node amber">MARGIN ANALYSIS</span></div><div class="cs-section"><p>Costing-based COPA remains optional/de-emphasized. <b>Operating Concern</b> must be activated for the Controlling Area before postings flow. <b>Cost Component Split</b> transfers from CO Day 7 for full COGS breakdown.</p></div><table class="cs-table"><tr><th>Approach</th><th>FI Reconciliation</th></tr><tr><td>Account-based</td><td>Automatic — same G/L data as FI</td></tr><tr><td>Costing-based (legacy)</td><td>Historically could drift — separate value fields</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Account-based vs costing-based reconciliation</b> — the #1 CO-9 comparison.</p><p>• <b>Attributed Profitability Segments</b> recover under-characterized postings, not lost data.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• G/L accounts, not value fields — that\'s the structural reconciliation win.</p><p>• Reports live off ACDOCA — no separate COPA table.</p></div>',

  'co-10': '<div class="cs-bar">Material Ledger — Always Active in S/4</div><div class="cs-flow"><span class="cs-node">MATERIAL LEDGER (mandatory)</span><span class="cs-arrow">►</span><span class="cs-node green">ACTUAL COSTING (optional)</span></div><div class="cs-section"><p>"Is ML optional in S/4?" — <b>No.</b> ML always active; only Actual Costing is optional. <b>Price Determination 3</b> enables full actual costing with Periodic Unit Price (PUP).</p></div><table class="cs-table"><tr><th>Determination</th><th>Redistributes</th></tr><tr><td>Single-level</td><td>Only within the material\'s own level</td></tr><tr><td>Multilevel</td><td>Down through the full BOM to components</td></tr></table><div class="cs-bar amber">Actual Costing Run Sequence</div><div class="cs-section"><p>Selection → sequence determination → single-level → multilevel → revaluation of consumption → WIP revaluation → post closing.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Is ML optional?" — reliable S/4 knowledge filter.</b> No, only actual costing is.</p><p>• <b>Price Control S + ML actual costing = the standard design.</b></p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• ML mandatory, Actual Costing optional. Never the reverse.</p><p>• AVR = parallel valuation, doesn\'t touch primary legal view.</p></div>',

  'int-1': '<div class="cs-bar">One Document, One Table</div><div class="cs-flow"><span class="cs-node">FI LINE</span><span class="cs-node green">=</span><span class="cs-node amber">CO LINE</span><span class="cs-arrow">►</span><span class="cs-node">ACDOCA</span></div><div class="cs-section"><p><b>Cost element as G/L account</b> is the reconciliation-eliminating mechanism — no separate CO-only object exists to drift out of sync with FI.</p></div><table class="cs-table"><tr><th>ECC</th><th>S/4</th></tr><tr><td>Reconciliation Ledger, COFI</td><td>Not needed — structural sync via Universal Journal</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"How does S/4 keep FI/CO in sync?"</b> — expected answer is structural, not procedural.</p><p>• <b>What still needs investigation:</b> derivation gaps, Functional Area mismatches — not a scheduled reconciliation run.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• One document. Not two documents kept in sync.</p><p>• Cross-CC CO postings still need CO Day 1\'s shared COA + fiscal year variant prerequisite.</p></div>',

  'int-2': '<div class="cs-bar">Accounting Entry at Goods Receipt — Near-Universal Question</div><div class="cs-flow"><span class="cs-node">GR</span><span class="cs-arrow">►</span><span class="cs-node green">INVENTORY DEBIT</span><span class="cs-node amber">GR/IR CREDIT</span></div><div class="cs-flow"><span class="cs-node">IR</span><span class="cs-arrow">►</span><span class="cs-node green">GR/IR DEBIT</span><span class="cs-node amber">VENDOR PAYABLE CREDIT</span></div><table class="cs-table"><tr><th>OBYC Key</th><th>Purpose</th></tr><tr><td>BSX</td><td>Inventory posting</td></tr><tr><td>WRX</td><td>GR/IR clearing</td></tr><tr><td>GBB</td><td>Offsetting entry (VBR/VAX/VAY/ZOB/ZOF/BSA modifiers)</td></tr><tr><td>PRD</td><td>Price differences</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"What is the accounting entry at GR?"</b> — know it cold, near-universal question.</p><p>• <b>MMPV (MM period) ≠ FI period</b> — both must be open for goods movements.</p><p>• <b>S vs V:</b> S posts differences to PRD; V updates moving average directly.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• GR: Inventory Dr / GR-IR Cr. IR: GR-IR Dr / Vendor Cr.</p><p>• Three-way match: PO, GR, IR — tolerance keys trigger invoice blocks.</p></div>',

  'int-3': '<div class="cs-bar">O2C Accounting Impact — Two Points Only</div><div class="cs-flow"><span class="cs-node">ORDER (no entry)</span><span class="cs-arrow">►</span><span class="cs-node green">PGI: COGS Dr / Inventory Cr</span><span class="cs-arrow">►</span><span class="cs-node amber">BILLING: Receivable Dr / Revenue Cr</span></div><div class="cs-section"><p><b>VKOA:</b> Application V, condition type KOFI/KOFK, Account Assignment Group — maintained on <b>both customer AND material master.</b></p></div><table class="cs-table"><tr><th>Account Key</th><th>Purpose</th></tr><tr><td>ERL</td><td>Revenue</td></tr><tr><td>ERS</td><td>Sales deductions</td></tr><tr><td>MWS</td><td>Output tax</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Billing not released to accounting"</b> chain: VKOA gap, account assignment group blank on customer OR material, closed period, missing segment.</p><p>• <b>PGI is CO-relevant</b> — COGS hits Primary Costs account type.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Accounting starts at PGI and Billing, nowhere earlier.</p><p>• Account Assignment Group lives on customer AND material — both required.</p></div>',

  'int-4': '<div class="cs-bar">Work Center ↔ Cost Center ↔ Activity Type</div><div class="cs-flow"><span class="cs-node">WORK CENTER</span><span class="cs-arrow">►</span><span class="cs-node green">COST CENTER</span><span class="cs-arrow">►</span><span class="cs-node amber">ACTIVITY TYPE</span></div><div class="cs-section"><p><b>Goods Issue, Activity Confirmation, Goods Receipt</b> — the three cost-bearing production order events. Confirmation → activity allocation → cost center credit, order debit.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>"Cost center over/under-absorbed"</b> → trace to activity price (plan) vs actual cost, resolved at CO Day 4 revaluation.</p><p>• <b>Missing Routing breaks the cost estimate, not the production order</b> — planning-time vs execution-time dependency.</p><p>• <b>Confirmation reversal</b> generates an offsetting activity allocation entry.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Capacity/formula errors at PP level distort activity price at CO level.</p><p>• Co-products need explicit cost-splitting rules; by-products use credit handling.</p></div>',

  'int-5': '<div class="cs-bar">WBS — A True CO Object</div><div class="cs-flow"><span class="cs-node">PROJECT DEFINITION</span><span class="cs-arrow">►</span><span class="cs-node green">WBS (true CO object)</span><span class="cs-arrow">►</span><span class="cs-node amber">SETTLEMENT</span></div><div class="cs-section"><p><b>Investment Measure → AuC → Fixed Asset</b>, governed by Investment Program + Appropriation Requests. <b>Symbolic Account → G/L Account mapping</b> is the core HCM payroll integration question.</p></div><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>WBS vs Internal Order</b> — project structure suits multi-year, multi-deliverable work.</p><p>• <b>IM/PS availability control</b> adds a capital-approval governance layer Internal Orders don\'t inherently have.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• WBS can be true CO object — receives cost from purchasing AND sales.</p><p>• Payroll: symbolic account is the intermediate mapping to G/L.</p></div>',

  'int-6': '<div class="cs-bar">Central Finance ≠ Migration Path</div><div class="cs-flow"><span class="cs-node">SOURCE SYSTEMS</span><span class="cs-arrow">►</span><span class="cs-node green">SLT REPLICATION</span><span class="cs-arrow">►</span><span class="cs-node amber">CENTRAL S/4 (reporting)</span></div><div class="cs-section"><p>Central Finance = <b>reporting/central-processing deployment</b>, not itself a migration. <b>Group Reporting</b> replaces BCS/BPC — Consolidation Units, Trading Partner elimination, reads from ACDOCA.</p></div><table class="cs-table"><tr><th>Tool</th><th>Status</th></tr><tr><td>Migration Cockpit (LTMC/LTMOM)</td><td>Current standard</td></tr><tr><td>LSMW</td><td>Deprecated for S/4</td></tr></table><div class="cs-trap"><h4>Interview Traps</h4><p>• <b>Central Finance is not a migration path.</b> The #1 trap in this tab.</p><p>• <b>Brownfield FICO prerequisites:</b> BP conversion, New AA activation, ML activation, CVI.</p></div><div class="cs-tip"><h4>30-Second Recall</h4><p>• Group Reporting vs BPC vs BCS — Group Reporting is the S/4 direction.</p><p>• Greenfield / Brownfield / Bluefield — three conversion strategies.</p></div>',
};

